const source = $('Execute Workflow Trigger').item.json || {};
const args = source.args && typeof source.args === 'object' ? source.args : source;
const tool = String(source.tool || '').trim();
const tasklistId = encodeURIComponent(String(args.tasklistId || '@default'));
const taskId = encodeURIComponent(String(args.taskId || ''));
const base = `https://tasks.googleapis.com/tasks/v1/lists/${tasklistId}/tasks`;
let method = 'GET';
let url = base;
let body = {};
const limit = Math.max(1, Math.min(Number(args.limit || 20), 100));
if (tool === 'tasks.list') url += `?maxResults=${limit}&showCompleted=false`;
else if (tool === 'tasks.list_due') { const day = String(args.date || new Date().toISOString().slice(0,10)); url += `?maxResults=${limit}&showCompleted=false&dueMin=${encodeURIComponent(day+'T00:00:00.000Z')}&dueMax=${encodeURIComponent(day+'T23:59:59.999Z')}`; }
else if (tool === 'tasks.list_overdue') url += `?maxResults=${limit}&showCompleted=false&dueMax=${encodeURIComponent(new Date().toISOString())}`;
else if (tool === 'tasks.create') { method='POST'; body={title:String(args.title||''),notes:String(args.notes||''),due:String(args.due||'')||undefined}; }
else if (tool === 'tasks.update') { method='PATCH'; url += `/${taskId}`; body=Object.fromEntries(Object.entries({title:args.title,notes:args.notes,due:args.due}).filter(([,v])=>String(v||'').trim())); }
else if (tool === 'tasks.complete') { method='PATCH'; url += `/${taskId}`; body={status:'completed'}; }
else if (tool === 'tasks.delete') { method='DELETE'; url += `/${taskId}`; }
else return [{json:{ok:false,error:`Unsupported Tasks tool: ${tool}`,tool}}];
if (['tasks.create'].includes(tool) && !String(args.title||'').trim()) return [{json:{ok:false,error:'Task title is required.',tool}}];
if (['tasks.update','tasks.complete','tasks.delete'].includes(tool) && !String(args.taskId||'').trim()) return [{json:{ok:false,error:'Task id is required.',tool}}];
return [{json:{...source,ok:true,tool,method,url,body}}];
